export type IconNameA = keyof typeof PH;
export type IconNameB = keyof typeof HG;

type Props = { className?: string; label?: string };

function a11y(label?: string) {
  return label ? { role: "img", "aria-label": label } : { "aria-hidden": true as const };
}

/** Иконка варианта A (Phosphor Light). Декоративная, если нет `label`. */
export function IconA({ name, className, label }: Props & { name: IconNameA }) {
  return <svg viewBox="0 0 256 256" fill="currentColor" className={className} {...a11y(label)} dangerouslySetInnerHTML={{ __html: PH[name] }} />;
}

/** Иконка варианта B (Hugeicons). Декоративная, если нет `label`. */
export function IconB({ name, className, label }: Props & { name: IconNameB }) {
  return <svg viewBox="0 0 24 24" fill="none" className={className} {...a11y(label)} dangerouslySetInnerHTML={{ __html: HG[name] }} />;
}

export type IconCommon = IconNameA & IconNameB;

/** Иконка набора своего варианта по общему имени. */
export function Ico({ v, name, className, label }: Props & { v: "a" | "b"; name: IconCommon }) {
  return v === "a" ? <IconA name={name} className={className} label={label} /> : <IconB name={name} className={className} label={label} />;
}
